from lib import *
S = SS('l39')
steps = [
    step("用 git check-ignore -v 逐个验证 8 条模式:*.log 匹配任意深度的 .log(a.log、sub/deep/b.log 都忽略);/todo.txt 开头的斜杠锚定到根目录,sub/todo.txt 不被忽略;build/ 结尾的斜杠只匹配目录,任意深度的 build 目录都忽略;**/tmp 匹配任意深度(包括根目录的 tmp);doc/*.md 的 * 不跨目录,doc/a.md 忽略、doc/sub/b.md 不忽略;logs/**/*.txt 的 ** 可跨多级目录;foo?.c 的 ? 匹配一个字符,foo1.c 忽略、foo12.c 不忽略;[ab]x.c 字符集,ax.c 忽略、cx.c 不忽略。输出里的“.gitignore:3:build/”就是匹配的文件、行号和模式。", t=tl(S(1)), mark=lidx(S(1), 'sub/todo.txt', 'doc/sub/b.md', 'foo12.c', 'cx.c'), done=lidx(S(1), 'a.log ', 'sub/deep/b.log', 'todo.txt ', 'build ', 'x/tmp', 'doc/a.md', 'logs/x/y/a.txt', 'foo1.c', 'ax.c'), kv=KV([['*  ?  [..]', '不跨目录'], ['**', '跨任意多级目录'], ['开头的 /', '锚定到 .gitignore 所在目录'], ['结尾的 /', '只匹配目录']], ['**'])),
    step("取反 ! 能把前面忽略的重新包含:*.log 加 !important.log,important.log 的最后匹配是取反模式,不忽略(git status 里能看到 ?? important.log);cache/* 加 !cache/keep.txt,cache/keep.txt 也被救回(?? cache/keep.txt),cache/o.o 仍忽略。但 build/ 加 !build/keep.txt 不起作用:build/keep.txt 仍然忽略(命中 build/ 那一行)——父目录一旦被排除,git 根本不会进去看,里面的文件救不回来。把 build/ 改成 build/*(排除目录里的内容而不是目录本身)才行。", t=tl(S(2)), mark=lidx(S(2), 'build/keep.txt', 'build/o.o'), done=lidx(S(2), 'important.log', 'cache/keep.txt', 'cache/o.o', '?? cache/keep.txt', '?? important.log'), kv=KV([['!pattern', '重新包含'], ['父目录被忽略', '里面的取反无效'], ['办法', '用 dir/* 代替 dir/']], ['父目录被忽略'])),
    step("斜杠的含义:/a.txt 只匹配根目录的 a.txt,sub/a.txt 不忽略;b.txt(没有斜杠)匹配任意深度,sub/b.txt 也忽略;c/ 结尾斜杠只匹配目录:c/f 忽略,但 sub 里一个叫 c 的文件(sub/c)不忽略;d/e.txt(中间有斜杠)也是锚定的:d/e.txt 忽略,sub/d/e.txt 不忽略。规则:模式里除结尾以外出现斜杠,就锚定到 .gitignore 所在目录。", t=tl(S(3)), mark=lidx(S(3), 'sub/a.txt', 'sub/c', 'sub/d/e.txt'), done=lidx(S(3), 'a.txt ', 'b.txt ', 'sub/b.txt', 'c/f', 'd/e.txt'), kv=KV([['开头的 /', '锚定'], ['中间的 /', '也锚定'], ['结尾的 /', '只匹配目录'], ['没有 /', '任意深度']], ['中间的 /'])),
    step("多个来源的优先级:根 .gitignore 里 *.tmp;sub/.gitignore 里 !keep.tmp 和 *.dat;.git/info/exclude 里 *.secret;core.excludesFile(全局文件)里 *.bak。结果:sub/keep.tmp 被子目录的取反模式救回(不忽略),根目录的 keep.tmp 仍被根 .gitignore 忽略;x.dat 在根目录不忽略,sub/x.dat 在 sub 里被忽略(子目录的规则只管子目录);a.secret 来自 .git/info/exclude 第 1 行;a.bak 来自全局文件。离文件越近的 .gitignore 优先级越高,同一文件里后面的行覆盖前面的行。", t=tl(S(4)), mark=lidx(S(4), 'sub/keep.tmp', 'sub/.gitignore:2:*.dat', '.git/info/exclude', 'global_ignore'), done=lidx(S(4), 'keep.tmp ', 'x.dat', 'a.tmp'), kv=KV([['子目录 .gitignore', '覆盖上层,只管该目录'], ['.git/info/exclude', '仓库私有,不入库'], ['core.excludesFile', '全局,所有仓库'], ['同一文件', '后面的行覆盖前面']], ['子目录 .gitignore'])),
    step("忽略只对未跟踪的文件有效:先提交了 secret.env,事后加进 .gitignore 并修改它,git status 仍然显示 M secret.env。git check-ignore -v secret.env 默认没有输出、退出码 1(对已跟踪的文件直接说“不忽略”);加 --no-index 才看到 .gitignore:1:secret.env 匹配。git rm --cached 取消跟踪后,它才变成被忽略的未跟踪文件(git ls-files --others --ignored 列出它),此时普通的 git add 被拒绝:The following paths are ignored by one of your .gitignore files,要 git add -f 才能强行加回来。", t=tl(S(5)), mark=lidx(S(5), 'M secret.env', 'ignored by one of your .gitignore files', 'git check-ignore -v --no-index'), done=lidx(S(5), '.gitignore:1:secret.env', 'D  secret.env', 'git add -f'), kv=KV([['已跟踪', '不受 .gitignore 影响'], ['check-ignore', '要 --no-index 才忽略跟踪状态'], ['git rm --cached', '取消跟踪'], ['git add -f', '强制加入被忽略的文件']], ['已跟踪'])),
    step("看被忽略的文件:git status --short --ignored 把它们标成 !!(!! a.o、!! sub/ —— sub 里全是被忽略的文件,只列目录);git ls-files -o -i --exclude-standard 列出 a.o 和 sub/b.o;git clean -n -X 只预览清理被忽略的文件(Would remove a.o),不带 -d 不会进入目录,加 -d 之后才包含 sub/。-n 是 dry run,不加 -n 才真的删。", t=tl(S(6)), mark=lidx(S(6), '!! a.o', '!! sub/', 'Would remove sub/'), done=lidx(S(6), 'sub/b.o', 'Would remove a.o'), kv=KV([['status --ignored', '!! 标记被忽略的'], ['ls-files -o -i', '按文件列出'], ['clean -X', '只清被忽略的,-d 包含目录'], ['-n', 'dry run']], ['clean -X'])),
]
A = mkarti('l39', 39, 'Git,gitignore,check-ignore,git status,真实验证,动画演示',
    '用 git check-ignore -v 逐条验证 .gitignore 的写法:* ? [] 不跨目录、** 跨多级、开头与中间的 / 锚定、结尾的 / 只匹配目录;! 取反在父目录被忽略时无效;子目录 .gitignore、.git/info/exclude、core.excludesFile 的优先级;已跟踪的文件不受忽略影响(check-ignore 默认直接说不忽略,要 --no-index);status --ignored、ls-files -o -i、clean -X 的用法。',
    '.gitignore 里的星号、双星号、斜杠到底怎么匹配?取反为什么有时无效?多个 ignore 文件谁优先?这篇不背规则,直接用 git check-ignore -v 对每条模式逐路径验证,看匹配的文件、行号和结果。',
    [('父目录', '父目录已被忽略时,里面的 !取反 无效(build/ + !build/keep.txt);改用 build/* 才有效'), ('check-ignore -v', '显示每条路径被哪个文件第几行的哪条模式匹配;对已跟踪的文件需要 --no-index'), ('已跟踪不受影响', '事后把已提交的文件加进 .gitignore,git 仍然跟踪它,要 git rm --cached 才取消')],
    [('通配符', '<p><code>*</code>、<code>?</code>、<code>[...]</code> 不跨目录分隔符,<code>**</code> 才能跨任意多级目录。模式里没有斜杠(除结尾)时匹配任意深度,开头或中间有斜杠就锚定到 .gitignore 所在目录;结尾的斜杠表示只匹配目录。</p>'),
     ('取反', '<p><code>!</code> 重新包含前面忽略的路径,但 git 不会进入被忽略的目录,所以不能救回里面的文件。想保留目录里的少数文件,要忽略目录内容(<code>dir/*</code>)而不是目录本身。<code>git check-ignore -v</code> 也会打印取反模式,看到 <code>!</code> 开头就是“不忽略”。</p>'),
     ('斜杠', '<p><code>/a.txt</code> 只管根目录,<code>b.txt</code> 管所有层,<code>c/</code> 只管目录,<code>d/e.txt</code> 因为中间有斜杠也被锚定。</p>'),
     ('优先级', '<p>离文件越近的 .gitignore 优先级越高,同一个文件里后面的行覆盖前面。此外还有 <code>.git/info/exclude</code>(仓库私有,不入库)和 <code>core.excludesFile</code>(全局)。</p>'),
     ('已跟踪的文件', '<p>.gitignore 只作用于未跟踪的文件。已经提交的文件事后被加进去,仍然会被跟踪、修改仍显示在 status 里;<code>git rm --cached</code> 取消跟踪后才算被忽略。被忽略的文件要 <code>git add -f</code> 强制添加。</p>'),
     ('查看被忽略的', '<p><code>git status --ignored</code> 用 <code>!!</code> 标出,<code>git ls-files -o -i --exclude-standard</code> 列出,<code>git clean -X</code> 只清理被忽略的(<code>-n</code> 先预览,<code>-d</code> 包含目录)。</p>')],
    steps,
    [ENV_I_GIT + '。所有结果来自 git check-ignore -v 与 git status;core.excludesFile 指向实验专用目录里的文件;输出里 a.bak 的来源路径显示为简化后的路径',
     '没有验证:核心的 gitignore 实现细节(如 trailing space、转义 \\# 与 \\!,没有逐项试);忽略大小写的文件系统上 core.ignoreCase 的影响;符号链接是否被忽略;子模块目录与 .gitignore;.gitattributes 的 export-ignore;git check-ignore --stdin 批量模式'],
    '.gitignore 规则')
